import test from 'node:test';
import assert from 'node:assert/strict';
import {createBattle,actBattle,presentedActBattle,endTurn,presentedEndTurn,getReachable,stanceCost,actionCosts,canSee,teamCanSee,lookPreview,artilleryContact,firearmShotOptions} from '../game/tactical.js';
import {validateBattleSnapshot} from '../game/validate-battle.js';
