const actor=(b,id='guard')=>b.units.find(u=>u.id===id),strict={shotSafety:knownRouteBystanderShotSafety};
const rounds=u=>Object.values(unitAmmunitionByType(u)).reduce((sum,count)=>sum+count,0);

// Nine independent portable defenders. Every post, wound, finite load, roof,
// observer and cannon precedes the factory; no campaign or failed result is input.
function arena({edge=false,lowCover=false,blocked=false,clinical=false,crew=false,empty=false,quiet=false}={}){
 const width=40,height=20,base={hp:100,maxHp:100,bleeding:0,bandaged:0,energy:100,fatigue:0,morale:90,weapon:1800,loaded:1,ammo:5,condition:100,medical:0,medkits:0,stance:'standing',facing:0,activeSlot:'primary',marksmanship:90,patrol:false,overwatch:false};
 const players=[
  {...base,id:'guard',x:5,y:edge?4:6,tacticalLevel:1,stance:edge?'prone':'standing',facing:blocked?2:0,...(empty?{loaded:0}:{})},
  {...base,id:'observer',x:7,y:4,tacticalLevel:1,weapon:0,loaded:0,ammo:0,activeSlot:'unarmed'},
  {...base,id:'physician',x:20,y:9,tacticalLevel:1,medical:90,medkits:3,activeSlot:clinical?'medical':'primary'},
  {...base,id:'patient',x:20,y:8,tacticalLevel:1,...(clinical?{hp:30,bleeding:3,bandaged:0}:{})},
  {...base,id:'reserve1',x:21,y:crew?12:8,tacticalLevel:crew?0:1},
  {...base,id:'reserve2',x:22,y:crew?11:8,tacticalLevel:crew?0:1},
  {...base,id:'reserve3',x:21,y:9,tacticalLevel:1},
  {...base,id:'reserve4',x:22,y:9,tacticalLevel:1},
  {...base,id:'courier',x:25,y:12,tacticalLevel:0,weapon:1804,loaded:1,ammo:4},
 ];
 const roofWidth=blocked?9:4,upperSurfaces=[...Array.from({length:roofWidth*5},(_,i)=>{const x=4+i%roofWidth,y=4+Math.floor(i/roofWidth);return {id:'roof:'+i,x,y,tacticalLevel:1,elevation:3,type:'floor',kind:'roof',blocked:false,cover:lowCover&&!(x===5&&y===6)?0:30};}),
  ...Array.from({length:12},(_,i)=>({id:'annex:'+i,x:20+i%4,y:7+Math.floor(i/4),tacticalLevel:1,elevation:3,type:'floor',kind:'roof',blocked:false,cover:30}))];
 const options={id:'declared-rescue-clinic-roof',width,height,hour:12,seed:45,exploration:quiet,climbLinks:[],upperSurfaces,
  tiles:Array.from({length:width*height},(_,i)=>({x:i%width,y:Math.floor(i/width),type:'grass',blocked:false,cover:0})),
  enemies:quiet?[]:[{id:'target',x:blocked?11:5,y:blocked?6:2,tacticalLevel:blocked?1:0,hp:500,maxHp:500,bleeding:0,bandaged:0,weapon:0,loaded:0,ammo:0,medical:0,medkits:0,patrol:false,overwatch:false}],
  npcs:blocked?[{id:'resident',name:'Known clinic resident',x:8,y:6,tacticalLevel:1,hp:100,maxHp:100,bleeding:0,bandaged:0,civilianHealthVersion:1,civilianWoundVersion:1,energy:100,unconscious:false,stance:'standing'}]:[],
  artillery:[{id:'clinic-gun',type:'bronze4',side:'player',x:22,y:12,facing:0,loaded:false,ammo:2}],
 };
 const declaration=structuredClone({players,options}),battle=createBattle(players,options);
 assert.deepEqual({players,options},declaration);assert.equal(battle.units.filter(u=>u.side==='player').length,9);assert.deepEqual(validateBattleSnapshot(JSON.parse(JSON.stringify(battle))),battle);return battle;
}

function replay(start,orders){
 let direct=start,shown=start,restored=validateBattleSnapshot(JSON.parse(JSON.stringify(start)));
 for(const order of orders){direct=actBattle(direct,order);assert.equal(direct.lastError,null,JSON.stringify(order));shown=presentedActBattle(shown,order).state;assert.deepEqual(shown,direct);restored=actBattle(restored,order);assert.equal(restored.lastError,null);restored=validateBattleSnapshot(JSON.parse(JSON.stringify(restored)));assert.deepEqual(restored,direct);}
 return direct;
}
function fixed(start,after,{reloaded=[]}={}){
 for(const key of ['tiles','upperSurfaces','climbLinks','artillery'])assert.deepEqual(after[key],start[key]);
 for(const u of start.units.filter(u=>u.side==='player')){
  const v=actor(after,u.id);for(const key of ['weapon','blade','weaponInstanceId','weaponMetadata','outfit','headwear','legwear'])assert.deepEqual(v[key],u[key]);
  const inventory=structuredClone(u.inventory);
  if(reloaded.includes(u.id)){const stacks=Object.entries(inventory).filter(([,stack])=>stack.kind==='ammunition'&&stack.ammoType==='musket_75');assert.equal(stacks.length,1);const [key,stack]=stacks[0];assert.ok(stack.count>1);inventory[key]={...stack,count:stack.count-1};assert.equal(v.ammo,u.ammo-1);}
  assert.deepEqual(v.inventory,inventory,'Every stack and item attribute stays exact except the one real reload debit.');
 }
}
function safeShot(b,u,order){
 assert.equal(order?.type,'fire');const target=actor(b,order.targetId),shot=firearmShotOptions(b,u,target,order.aim??0).find(option=>option.aim===(order.aim??0)&&option.hitLocation===(order.hitLocation??'torso'));assert.ok(shot?.chance>=25&&shot.damageFactor>0);assert.equal(knownRouteBystanderShotSafety(b,u,target)(shot),true);assert.deepEqual(firearmBystanderRisk(b,u,target,order.hitLocation??'torso'),{direct:[],scatter:[]});
}
function paidFiringPrefix(start,policy){
 let battle=start,unit=actor(battle),fire=policy.controller(battle,unit);const orders=[];
 for(let step=0;fire?.type==='stance'&&step<2;step++){
  assert.ok(['crouched','prone'].includes(fire.stance));assert.deepEqual(fire,northernClinicDefenseOrder(battle,unit));assert.equal(usefulRouteFiringPosture(publicRouteView(battle,unit),unit,fire,strict),true,'Every paid ordinary posture must leave an affordable safe useful shot.');
  const before=unit,cost=stanceCost(unit,fire.stance);orders.push(fire);battle=replay(start,orders);unit=actor(battle);assert.equal(unit.ap,before.ap-cost);assert.deepEqual(spacePoint(unit),spacePoint(before));assert.equal(battle.elapsedSeconds,start.elapsedSeconds+(start.roundTimeCharged?0:COMBAT_ROUND_SECONDS));assert.deepEqual(unitAmmunitionByType(unit),unitAmmunitionByType(before));assert.equal(unit.medkits,before.medkits);assert.equal(unit.hp,before.hp);fixed(start,battle);
  fire=policy.controller(battle,unit);
 }
 safeShot(battle,unit,fire);return {battle,unit,orders,fire};
}

test('nine declared posts retain their roles while one roof rifle pays a covered lane and a finite safe shot',()=>{
 const start=arena(),before=structuredClone(start),guard=actor(start),policy=rescueClinicDefenseController(start),view=publicRouteView(start,guard);
 assert.equal(northernClinicDefenseOrder(start,guard),null);assert.equal(usefulRouteRifleShot(view,guard,strict),null);assert.equal(policy.roles.physicianId,'physician');assert.ok(!policy.roles.rifleIds.includes('physician'));assert.ok(!policy.roles.rifleIds.includes('courier'));
 const move=policy.controller(start,guard);assert.equal(move?.type,'move');const point=getReachable(view,guard,{stopAt:p=>sameCell(p,move)})[0];assert.ok(point.cost>0&&point.cost<=20&&Math.hypot(point.x-guard.x,point.y-guard.y)<=3);assert.ok(point.path.every(p=>sameSurface(p,guard)&&(p.kind===undefined||p.kind==='move')&&(surfaceAt(view,p).cover??0)>=(surfaceAt(view,guard).cover??0)));
 const quote=paidHospitalRoofWalkPreview(view,guard,point);assert.ok(quote&&usefulRouteRifleShot(quote.view,quote.actor,strict));const moved=replay(start,[move]),next=actor(moved);assert.ok(sameCell(next,point));assert.equal(next.ap,guard.ap-point.cost);assert.ok(next.energy<guard.energy);assert.equal(moved.elapsedSeconds,start.elapsedSeconds+COMBAT_ROUND_SECONDS);
 const prefix=paidFiringPrefix(moved,policy),{fire}=prefix,cost=actionCosts(prefix.battle,prefix.unit,actor(prefix.battle,fire.targetId)),after=replay(start,[move,...prefix.orders,fire]);assert.equal(actor(after).ap,prefix.unit.ap-cost.fire-fire.aim*cost.aim);assert.equal(after.elapsedSeconds,prefix.battle.elapsedSeconds);assert.equal(rounds(actor(after)),rounds(guard)-1);assert.equal(actor(after).condition,guard.condition-1);assert.equal(actor(after).tacticalLevel,1);
 for(const u of start.units.filter(u=>u.side==='player'&&u.id!=='guard')){assert.deepEqual(spacePoint(actor(after,u.id)),spacePoint(u));assert.equal(rounds(actor(after,u.id)),rounds(u));assert.equal(actor(after,u.id).medkits,u.medkits);}
 fixed(start,after);assert.deepEqual(start,before);
});

test('a prone roof edge pays its rise and useful ordinary posture before finite fire and reload',()=>{
 const start=arena({edge:true}),before=structuredClone(start),guard=actor(start),policy=rescueClinicDefenseController(start),target=actor(start,'target');
 assert.equal(canSee(start,guard,target),false);assert.equal(northernClinicDefenseOrder(start,guard),null);assert.equal(coordinatedHospitalBattery(start).controller(start,guard),null);const rise=policy.controller(start,guard);assert.deepEqual(rise,{type:'stance',unitId:'guard',stance:'standing'});
 const stood=replay(start,[rise]),next=actor(stood);assert.equal(next.ap,guard.ap-stanceCost(guard,'standing'));assert.equal(next.stance,'standing');assert.deepEqual(spacePoint(next),spacePoint(guard));assert.equal(rounds(next),rounds(guard));assert.equal(stood.elapsedSeconds,start.elapsedSeconds+COMBAT_ROUND_SECONDS);
 const prefix=paidFiringPrefix(stood,policy),{fire}=prefix,orders=[rise,...prefix.orders,fire],fired=replay(start,orders),cost=actionCosts(prefix.battle,prefix.unit,actor(prefix.battle,fire.targetId));assert.deepEqual(fire,northernClinicDefenseOrder(prefix.battle,prefix.unit));assert.equal(actor(fired).ap,prefix.unit.ap-cost.fire-fire.aim*cost.aim);assert.equal(fired.elapsedSeconds,prefix.battle.elapsedSeconds);assert.equal(rounds(actor(fired)),rounds(guard)-1);assert.equal(actor(fired).condition,guard.condition-1);assert.equal(actor(fired).stance,prefix.unit.stance);const reload=policy.controller(fired,actor(fired));assert.equal(reload?.type,'reload');const loaded=replay(start,[...orders,reload]);assert.equal(actor(loaded).ap,actor(fired).ap-actionCosts(fired,actor(fired)).reload);assert.equal(actor(loaded).loaded,1);assert.equal(rounds(actor(loaded)),rounds(guard)-1);assert.equal(actor(loaded).stance,prefix.unit.stance);fixed(start,loaded,{reloaded:['guard']});assert.deepEqual(start,before);
});

test('unsafe cover and an actually spent posture budget keep the roof hold without stock or body grants',()=>{
 const holds=(b,policy)=>{const ordinary=northernClinicDefenseOrder(b,actor(b)),selected=policy.controller(b,actor(b));assert.ok(selected===null||['stance','look'].includes(selected.type),'No unsafe shot, descent or cover-losing move is added.');assert.deepEqual(selected,ordinary);};
 const start=arena({lowCover:true}),before=structuredClone(start),policy=rescueClinicDefenseController(start);assert.equal(usefulRouteRifleShot(publicRouteView(start,actor(start)),actor(start),strict),null);for(let callback=0;callback<3;callback++)holds(start,policy);assert.deepEqual(start,before);
 const blocked=arena({lowCover:true,blocked:true}),blockedBefore=structuredClone(blocked),safe=rescueClinicDefenseController(blocked);assert.equal(canSee(blocked,actor(blocked),blocked.npcs[0]),true);assert.ok(firearmBystanderRisk(blocked,actor(blocked),actor(blocked,'target'),'torso').direct.some(body=>body.id==='resident'));const ordinary=northernClinicDefenseOrder(blocked,actor(blocked));assert.deepEqual(ordinary,{type:'stance',unitId:'guard',stance:'crouched'});assert.equal(usefulRouteFiringPosture(publicRouteView(blocked,actor(blocked)),actor(blocked),ordinary,strict),false,'The ordinary crouch cannot leave a safe shot through the known resident.');assert.equal(safe.controller(blocked,actor(blocked)),null);fixed(blockedBefore,blocked);assert.deepEqual(blocked,blockedBefore);
 const edge=arena({edge:true}),original=structuredClone(edge),held=rescueClinicDefenseController(edge),orders=[];let spent=edge;
 for(let count=0;count<12;count++){const u=actor(spent),up=stanceCost(u,'standing'),down=stanceCost({...u,stance:'standing'},'prone');if(u.ap<up+down)break;orders.push({type:'stance',unitId:u.id,stance:'standing'},{type:'stance',unitId:u.id,stance:'prone'});spent=replay(edge,orders);}
 assert.ok(orders.length>0);const u=actor(spent),paid=stanceCost(u,'standing'),posed={...u,stance:'standing',movementMode:'walk',weaponReady:false,momentum:0,ap:u.ap-paid};assert.ok(posed.ap<actionCosts(spent,posed,actor(spent,'target')).fire);const snapshot=structuredClone(spent);assert.equal(held.controller(spent,u),null);assert.deepEqual(spent,snapshot);assert.equal(rounds(u),rounds(actor(edge)));fixed(edge,spent);assert.deepEqual(edge,original);
});

test('physician, actual contact crew and ground courier keep exact existing work; finite care and reload stay first',()=>{
 const start=arena({clinical:true,crew:true}),before=structuredClone(start),policy=rescueClinicDefenseController(start);assert.equal(policy.roles.physicianId,'physician');assert.deepEqual(new Set(policy.roles.crews[0].ids),new Set(['reserve1','reserve2']));
 for(const id of ['physician','reserve1','reserve2','courier']){assert.ok(!policy.roles.rifleIds.includes(id));assert.deepEqual(policy.controller(start,actor(start,id)),northernClinicDefenseOrder(start,actor(start,id)));}
 assert.ok(artilleryContact(start,actor(start,'reserve1'),start.artillery[0]));const aid=policy.controller(start,actor(start,'physician'));assert.deepEqual(aid,{type:'useItem',unitId:'physician',targetId:'patient'});const after=replay(start,[aid]);assert.equal(actor(after,'physician').medkits,actor(start,'physician').medkits-1);assert.ok(actor(after,'patient').bleeding<actor(start,'patient').bleeding);fixed(start,after);assert.deepEqual(start,before);
 const empty=arena({empty:true}),snapshot=structuredClone(empty),loading=rescueClinicDefenseController(empty),reload=loading.controller(empty,actor(empty));assert.deepEqual(reload,northernClinicDefenseOrder(empty,actor(empty)));assert.equal(reload?.type,'reload');const loaded=replay(empty,[reload]);assert.equal(actor(loaded).loaded,1);assert.equal(rounds(actor(loaded)),rounds(actor(empty)));fixed(empty,loaded,{reloaded:['guard']});assert.deepEqual(empty,snapshot);
});

test('nineteen ordinary quiet end turns retain the original turn-twenty standing search release',()=>{
 const start=arena({edge:true,quiet:true}),before=structuredClone(start),policy=rescueClinicDefenseController(start);assert.equal(start.turn,1);assert.equal(policy.controller(start,actor(start)),null);
 let waited=start,restored=validateBattleSnapshot(JSON.parse(JSON.stringify(start)));
 for(let index=0;index<19;index++){
  waited=endTurn(waited);assert.equal(waited.lastError,null);assert.equal(waited.status,'active');restored=endTurn(restored);assert.equal(restored.lastError,null);restored=validateBattleSnapshot(JSON.parse(JSON.stringify(restored)));assert.deepEqual(restored,waited);
 }
 assert.equal(waited.turn,20);assert.equal(waited.mode,'exploration');const guard=actor(waited),ordinary=northernClinicDefenseOrder(waited,guard);assert.deepEqual(ordinary,{type:'stance',unitId:'guard',stance:'standing'});assert.equal(coordinatedHospitalBattery(start).controller(waited,guard),null);
 const rise=policy.controller(waited,guard);assert.deepEqual(rise,ordinary);const after=replay(waited,[rise]);assert.equal(actor(after).stance,'standing');assert.deepEqual(spacePoint(actor(after)),spacePoint(guard));assert.ok(after.elapsedSeconds>waited.elapsedSeconds);
 for(const u of start.units.filter(u=>u.side==='player')){assert.equal(rounds(actor(after,u.id)),rounds(u));assert.equal(actor(after,u.id).medkits,u.medkits);assert.equal(actor(after,u.id).hp,u.hp);}
 fixed(start,after);assert.deepEqual(start,before);
});

// These independent fields declare the lost-facing and ordinary unsafe-shot
// premises before Native. They do not reconstruct a failed clinic or its raid.
function declaredLookout({scatter=false}={}){
 const width=scatter?22:28,height=16,base={hp:100,maxHp:100,bleeding:0,bandaged:0,energy:100,fatigue:0,morale:90,weapon:1800,blade:0,loaded:1,ammo:8,condition:100,activeSlot:'primary',stance:'standing',movementMode:'walk',facing:2,marksmanship:100,dexterity:100,agility:100,strength:80,medical:0,medkits:0,patrol:false,overwatch:false};
 const players=[{...base,id:'guard',x:scatter?1:8,y:scatter?4:6,tacticalLevel:1,...(scatter?{weapon:1802,stance:'prone',movementMode:'prone'}:{})},
  {...base,id:'friend',x:scatter?8:19,y:scatter?5:8,tacticalLevel:1,weapon:0,loaded:0,ammo:0,activeSlot:'unarmed'},
  {...base,id:'physician',x:20,y:9,tacticalLevel:1,medical:90,medkits:3},
  {...base,id:'patient',x:18,y:8,tacticalLevel:1},
  {...base,id:'reserve1',x:18,y:9,tacticalLevel:1},
  {...base,id:'reserve2',x:19,y:9,tacticalLevel:1},
  {...base,id:'reserve3',x:20,y:8,tacticalLevel:1},
  {...base,id:'reserve4',x:21,y:8,tacticalLevel:1},
  {...base,id:'courier',x:21,y:12,tacticalLevel:0,weapon:1804,loaded:1,ammo:4}];
 const upperSurfaces=scatter?Array.from({length:width*height},(_,i)=>({id:'roof:'+i,x:i%width,y:Math.floor(i/width),tacticalLevel:1,elevation:3,type:'floor',kind:'roof',blocked:false,cover:30})):
  [...Array.from({length:20},(_,i)=>({id:'watch:'+i,x:8+i%4,y:4+Math.floor(i/4),tacticalLevel:1,elevation:3,type:'floor',kind:'roof',blocked:false,cover:30})),...Array.from({length:12},(_,i)=>({id:'ward:'+i,x:18+i%4,y:7+Math.floor(i/4),tacticalLevel:1,elevation:3,type:'floor',kind:'roof',blocked:false,cover:30}))];
 const options={id:'independent-clinic-lookout',width,height,hour:12,seed:45,upperSurfaces,climbLinks:scatter?[]:[{id:'watch-west',kind:'climb',from:{x:7,y:6,tacticalLevel:0},to:{x:8,y:6,tacticalLevel:1}}],
  tiles:Array.from({length:width*height},(_,i)=>({x:i%width,y:Math.floor(i/width),type:'grass',blocked:false,cover:0})),
  enemies:[{id:'target',x:scatter?8:1,y:scatter?4:6,tacticalLevel:scatter?1:0,hp:500,maxHp:500,bleeding:0,bandaged:0,energy:100,fatigue:0,weapon:0,loaded:0,ammo:0,medical:0,medkits:0,stance:'standing',facing:6,patrol:false,overwatch:false},...(scatter?[{id:'clear-lane',x:14,y:0,tacticalLevel:1,hp:500,maxHp:500,bleeding:0,bandaged:0,energy:100,fatigue:0,weapon:0,loaded:0,ammo:0,medical:0,medkits:0,stance:'standing',facing:6,patrol:false,overwatch:false}]:[])],npcs:[],artillery:[]};
 const declaration=structuredClone({players,options}),battle=createBattle(players,options);assert.deepEqual({players,options},declaration);assert.equal(battle.units.filter(unit=>unit.side==='player').length,9);assert.deepEqual(validateBattleSnapshot(JSON.parse(JSON.stringify(battle))),battle);return battle;
}

test('a restored east-facing roof pays to watch its authored west access before a real safe finite shot',()=>{
 const start=declaredLookout(),before=structuredClone(start),guard=actor(start),target=actor(start,'target'),policy=rescueClinicDefenseController(start);
 assert.equal(guard.facing,2);assert.equal(teamCanSee(start,'player',target),false);assert.equal(northernClinicDefenseOrder(start,guard),null);
 assert.equal(policy.roles.physicianId,'physician');assert.equal(policy.roles.rifleIds.includes('courier'),false);const post=policy.roles.lookouts.find(row=>row.id==='guard');assert.deepEqual(post,{id:'guard',x:7,y:6,tacticalLevel:0});
 const look=policy.controller(start,guard);assert.deepEqual(look,{type:'look',unitId:'guard',x:7,y:6,tacticalLevel:0});const quote=lookPreview(start,guard,look);assert.equal(quote.valid,true);assert.equal(quote.prepare,false);assert.ok(quote.pa>0);assert.deepEqual(policy.controller(start,guard),look,'A repeated quote does not spend an observation or mutate the controller.');
 const observed=replay(start,[look]),watcher=actor(observed);assert.equal(watcher.facing,quote.facing);assert.equal(watcher.ap,guard.ap-quote.pa);assert.deepEqual(spacePoint(watcher),spacePoint(guard));assert.equal(observed.elapsedSeconds,start.elapsedSeconds+COMBAT_ROUND_SECONDS);assert.equal(canSee(observed,watcher,actor(observed,'target')),true);assert.equal(rounds(watcher),rounds(guard));assert.equal(watcher.medkits,guard.medkits);
 const prefix=paidFiringPrefix(observed,policy),fire=prefix.fire,after=replay(start,[look,...prefix.orders,fire]);safeShot(prefix.battle,prefix.unit,fire);assert.equal(rounds(actor(after)),rounds(guard)-1);assert.equal(actor(after).condition,guard.condition-1);assert.deepEqual(spacePoint(actor(after)),spacePoint(guard));
 for(const unit of start.units.filter(unit=>unit.side==='player'&&unit.id!=='guard')){const other=actor(after,unit.id);assert.deepEqual(spacePoint(other),spacePoint(unit));assert.equal(other.hp,unit.hp);assert.equal(rounds(other),rounds(unit));assert.equal(other.medkits,unit.medkits);}
 fixed(start,after);assert.deepEqual(start,before);
});

test('an ordinary roof shot is revalidated against known friendly scatter before an actual safe alternative fires',()=>{
 const start=declaredLookout({scatter:true}),before=structuredClone(start),guard=actor(start),policy=rescueClinicDefenseController(start),ordinary=northernClinicDefenseOrder(start,guard);assert.equal(ordinary?.type,'fire');
 const target=actor(start,ordinary.targetId),option=firearmShotOptions(start,guard,target,ordinary.aim??0).find(option=>option.aim===(ordinary.aim??0)&&option.hitLocation===(ordinary.hitLocation??'torso'));assert.equal(knownRouteShotSafety(start,guard,target)(option),true);assert.equal(knownRouteBystanderShotSafety(start,guard,target)(option),false);assert.ok(firearmBystanderRisk(start,guard,target,ordinary.hitLocation).scatter.some(body=>body.id==='friend'));
 const fire=policy.controller(start,guard);assert.equal(fire?.targetId,'clear-lane');safeShot(start,guard,fire);const after=replay(start,[fire]),cost=actionCosts(start,guard,actor(start,fire.targetId));assert.equal(actor(after).ap,guard.ap-cost.fire-(fire.aim??0)*cost.aim);assert.equal(rounds(actor(after)),rounds(guard)-1);assert.equal(actor(after).condition,guard.condition-1);assert.equal(after.elapsedSeconds,start.elapsedSeconds+COMBAT_ROUND_SECONDS);
 for(const unit of start.units.filter(unit=>unit.side==='player'&&unit.id!=='guard')){const other=actor(after,unit.id);assert.deepEqual(spacePoint(other),spacePoint(unit));assert.equal(other.hp,unit.hp);assert.equal(rounds(other),rounds(unit));assert.equal(other.medkits,unit.medkits);}
 fixed(start,after);assert.deepEqual(start,before);
});

// Independent current-sighting geometry. Water keeps the unarmed opponent on
// its declared island while Native rounds earn the existing turn-20 boundary.
// The ground wall blocks the courier's own sight; the roof physician sees over
// the other side. Every role, wound, load and access link precedes the factory.
function investigationArena({courier={},crew=false,hiddenX=30,contact=true,care=false}={}){
 const width=32,height=14,base={hp:100,maxHp:100,bleeding:0,bandaged:0,energy:100,fatigue:0,morale:90,weapon:0,blade:0,loaded:0,ammo:0,condition:100,medical:0,medkits:0,stance:'prone',movementMode:'prone',facing:2,activeSlot:'unarmed',patrol:false,overwatch:false};
 const posts=[['guard',10,6],['physician',15,6],['patient',14,6],['west-owner',10,7],['north-owner',13,4],['reserve1',12,5],['reserve2',13,5],['reserve3',14,5]];
 const players=posts.map(([id,x,y])=>({...base,id,x,y,tacticalLevel:1,...(id==='physician'?{medical:90,medkits:3,activeSlot:care?'medical':'unarmed',stance:'standing',movementMode:'walk'}:{}),...(care&&id==='patient'?{hp:30,bleeding:3}:{}),...(crew&&['reserve1','reserve2'].includes(id)?{x:id==='reserve1'?1:3,y:9,tacticalLevel:0,weapon:1805,loaded:1,ammo:8,stance:'standing',movementMode:'walk',activeSlot:'primary'}:{})}));
 players.push({...base,id:'courier',x:2,y:6,tacticalLevel:0,weapon:1805,loaded:1,ammo:8,marksmanship:90,stance:'standing',movementMode:'walk',activeSlot:'primary',...courier});
 const options={id:'declared-clinic-ground-investigation',width,height,hour:12,seed:42,exploration:false,deferContact:true,
  tiles:Array.from({length:width*height},(_,i)=>{const x=i%width,y=Math.floor(i/width),wall=x===5&&y>=2&&y<=8||y===10,water=Math.abs(x-18)<=1&&Math.abs(y-6)<=1&&(x!==18||y!==6);return {x,y,type:wall?'wall':water?'water':'grass',blocked:wall||water,blocksSight:wall,cover:wall?40:0};}),
  upperSurfaces:Array.from({length:24},(_,i)=>({id:'investigation-roof:'+i,x:10+i%6,y:4+Math.floor(i/6),tacticalLevel:1,elevation:3,type:'floor',kind:'roof',blocked:false,cover:30})),
  climbLinks:[{id:'west',kind:'climb',from:{x:9,y:7,tacticalLevel:0},to:{x:10,y:7,tacticalLevel:1}},{id:'north',kind:'climb',from:{x:13,y:3,tacticalLevel:0},to:{x:13,y:4,tacticalLevel:1}}],
  enemies:[...(contact?[{...base,id:'target',x:18,y:6,tacticalLevel:0,stance:'standing',movementMode:'walk'}]:[]),{...base,id:'hidden',x:hiddenX,y:12,tacticalLevel:0,stance:'standing',movementMode:'walk'}],
  artillery:[{id:'finite-clinic-gun',type:'bronze4',side:'player',x:2,y:9,facing:2,loaded:true,ammo:2}],
 };
 const declaration=structuredClone({players,options}),battle=createBattle(players,options);assert.deepEqual({players,options},declaration);assert.equal(battle.units.filter(unit=>unit.side==='player').length,9);assert.deepEqual(validateBattleSnapshot(JSON.parse(JSON.stringify(battle))),battle);return battle;
}
function investigationStep(battle,action){
 const next=action.type==='endTurn'?endTurn(battle):actBattle(battle,action);assert.equal(next.lastError,null,JSON.stringify(action));
 const shown=action.type==='endTurn'?presentedEndTurn(battle).state:presentedActBattle(battle,action).state;assert.deepEqual(shown,next);
 const restored=validateBattleSnapshot(JSON.parse(JSON.stringify(battle))),saved=action.type==='endTurn'?endTurn(restored):actBattle(restored,action);assert.equal(saved.lastError,null);assert.deepEqual(validateBattleSnapshot(JSON.parse(JSON.stringify(saved))),next);return next;
}
function investigationReady(start){
 let battle=start;const orders=[];
 for(let round=0;round<19;round++){assert.equal(battle.status,'active');assert.equal(battle.phase,'player');assert.equal(battle.turn,round+1);const action={type:'endTurn'};battle=investigationStep(battle,action);orders.push(action);}
 assert.equal(battle.turn,20);return {battle,orders};
}
function investigationReplay(start,orders){let battle=start;for(const action of orders)battle=investigationStep(battle,action);return battle;}
function heldInvestigationPosts(start,after){
 for(const unit of start.units.filter(unit=>unit.side==='player'&&unit.id!=='courier')){const current=actor(after,unit.id);assert.deepEqual(spacePoint(current),spacePoint(unit));for(const key of ['hp','bleeding','bandaged','weapon','blade','inventory','loaded','ammo','medkits','condition'])assert.deepEqual(current[key],unit[key],unit.id+' '+key);}
 for(const key of ['tiles','upperSurfaces','climbLinks','artillery'])assert.deepEqual(after[key],start[key]);
}

test('the standing clinic courier pays a short public ground bound after a whole hold, then real safe fire and reload',()=>{
 const start=investigationArena(),before=structuredClone(start),policy=rescueClinicDefenseController(start),initial=actor(start,'courier'),target=actor(start,'target');
 assert.equal(canSee(start,initial,target),false);assert.equal(teamCanSee(start,'player',target),true);assert.equal(choosePlayerSharedSightingInvestigation(start,initial,target)?.type,'move');assert.equal(policy.sharedFallback(start,initial),null,'The existing turn-20 search boundary remains.');
 let {battle,orders}=investigationReady(start);const courier=actor(battle,'courier'),view=publicRouteView(battle,courier);
 for(const unit of battle.units.filter(unit=>unit.side==='player'))assert.equal(policy.controller(battle,unit),null,'The whole ordinary pass must actually hold.');
 const proposal=policy.sharedFallback(battle,courier);assert.equal(proposal?.type,'move');const path=getReachable(view,courier,{stopAt:point=>sameCell(point,proposal)})[0];assert.ok(path.cost>0&&path.cost<=24&&path.path.length<=3&&path.path.every(point=>sameSurface(point,courier)&&(point.kind===undefined||point.kind==='move')));const costs=actionCosts(battle,courier);assert.ok(courier.ap-path.cost>=costs.fire+2*costs.aim);
 const window=openingControlWindow(battle,{controller:policy.controller,sharedFallback:policy.sharedFallback});assert.deepEqual(window.orders,[proposal]);assert.deepEqual(window.sharedInvestigation,proposal);const moved=investigationStep(battle,proposal);assert.deepEqual(window.battle,moved);assert.equal(actor(moved,'courier').ap,courier.ap-path.cost);assert.ok(actor(moved,'courier').energy<courier.energy);assert.equal(moved.elapsedSeconds,battle.elapsedSeconds+COMBAT_ROUND_SECONDS);orders.push(proposal);battle=moved;
 let fire=null;
 for(let step=0;step<32&&!fire;step++){
  const unit=actor(battle,'courier'),ordinary=policy.controller(battle,unit),action=ordinary??policy.sharedFallback(battle,unit);
  if(action?.type==='fire'){safeShot(battle,unit,action);fire=action;break;}
  if(!action){assert.ok(battle.turn<28);const end={type:'endTurn'};battle=investigationStep(battle,end);orders.push(end);continue;}
  assert.ok(['move','look','stance'].includes(action.type));if(!ordinary&&action.type==='move'){const route=getReachable(publicRouteView(battle,unit),unit,{stopAt:point=>sameCell(point,action)})[0];assert.ok(route.cost>0&&route.cost<=24&&route.path.length<=3&&route.path.every(point=>sameSurface(point,unit)));}if(!ordinary&&action.type==='look'){const quote=lookPreview(publicRouteView(battle,unit),unit,action);assert.ok(quote.valid&&!quote.prepare&&quote.pa>0);}
  battle=investigationStep(battle,action);orders.push(action);heldInvestigationPosts(start,battle);
 }
 assert.ok(fire,'The fresh successful prefix must reach a real safe shot within the unchanged turn/action limits.');const shooter=actor(battle,'courier'),shotCost=actionCosts(battle,shooter,actor(battle,fire.targetId));battle=investigationStep(battle,fire);orders.push(fire);assert.equal(rounds(actor(battle,'courier')),rounds(initial)-1);assert.equal(actor(battle,'courier').ap,shooter.ap-shotCost.fire-(fire.aim??0)*shotCost.aim);assert.equal(actor(battle,'courier').condition,initial.condition-1);
 let reload=policy.controller(battle,actor(battle,'courier'));for(let prefix=0;reload?.type!=='reload'&&prefix<3;prefix++){assert.ok(!reload||reload.type==='stance'&&reload.stance==='crouched');const action=reload??{type:'endTurn'};battle=investigationStep(battle,action);orders.push(action);reload=policy.controller(battle,actor(battle,'courier'));}assert.equal(reload?.type,'reload');const empty=actor(battle,'courier'),reloadCost=actionCosts(battle,empty).reload;battle=investigationStep(battle,reload);orders.push(reload);assert.equal(actor(battle,'courier').ap,empty.ap-reloadCost);assert.equal(actor(battle,'courier').loaded,1);assert.equal(rounds(actor(battle,'courier')),rounds(initial)-1);heldInvestigationPosts(start,battle);assert.deepEqual(investigationReplay(start,orders),battle);assert.deepEqual(start,before);
});

