import {environmentUsePreview,environmentPreview} from '../game/tactical.js';
import {wallEdgeId,wallEdgeCells,wallEdgeCenter} from '../game/wall-geometry.js';

// A fresh sealed room has one public unlocked exit. The roof squad sees the
// living island contact; the courier cannot see or walk through the closed leaf.
// All walls, roles, wounds, finite property and optional patrol anchor are declared.
function doorInvestigationArena({courier={},locked=false,contact=true,hiddenX=22,knownTrap=false,blocked=false}={}){
 const width=26,height=17,base={hp:100,maxHp:100,bleeding:0,bandaged:0,energy:100,fatigue:0,morale:90,weapon:0,blade:0,loaded:0,ammo:0,condition:100,medical:0,medkits:0,stance:'prone',movementMode:'prone',facing:4,activeSlot:'unarmed',patrol:false,overwatch:false};
 const posts=[['guard',12,7],['physician',14,4],['patient',14,5],['west-owner',11,6],['north-owner',13,4],['reserve1',11,5],['reserve2',12,5],['reserve3',13,5]];
 const players=posts.map(([id,x,y])=>({...base,id,x,y,tacticalLevel:1,...(id==='guard'?{stance:'standing',movementMode:'walk'}:{}),...(id==='physician'?{medical:90,medkits:3}:{})}));
 players.push({...base,id:'courier',x:5,y:5,tacticalLevel:0,weapon:1800,loaded:1,ammo:8,marksmanship:100,dexterity:100,agility:100,experienceLevel:8,stance:'standing',movementMode:'walk',activeSlot:'primary',...courier});
 const wall=(id,x,y,axis,extra={})=>({id,x,y,axis,tacticalLevel:0,type:'wall',blocked:true,blocksSight:true,cover:40,...extra});
 const wallEdges=[...Array.from({length:5},(_,i)=>wall('west:'+i,4,3+i,'y')),...Array.from({length:5},(_,i)=>wall('east:'+i,8,3+i,'y')),...Array.from({length:4},(_,i)=>wall('north:'+i,4+i,3,'x')),...Array.from({length:4},(_,i)=>wall('south:'+i,4+i,8,'x',i===1?{type:'door',doorId:'clinic-exit',open:false,locked,cover:0,...(knownTrap?{trap:{type:'injury',damage:18,difficulty:30,armed:true,discoveredBy:['player']}}:{})}:{}))];
 const options={id:'fresh-clinic-public-door',width,height,hour:12,seed:42,exploration:false,deferContact:true,wallEdges,
  tiles:Array.from({length:width*height},(_,i)=>{const x=i%width,y=Math.floor(i/width),wall=y===14,water=Math.abs(x-15)<=1&&Math.abs(y-10)<=1&&(x!==15||y!==10),stop=blocked&&x===5&&y===7;return {x,y,type:wall||stop?'wall':water?'water':'grass',blocked:wall||water||stop,blocksSight:wall||stop,cover:wall||stop?40:x>=4&&x<=7&&y>=3&&y<=6?30:0};}),
  upperSurfaces:Array.from({length:16},(_,i)=>({id:'door-roof:'+i,x:11+i%4,y:4+Math.floor(i/4),tacticalLevel:1,elevation:3,type:'floor',kind:'roof',blocked:false,cover:30})),
  climbLinks:[{id:'west-access',kind:'climb',from:{x:10,y:6,tacticalLevel:0},to:{x:11,y:6,tacticalLevel:1}},{id:'north-access',kind:'climb',from:{x:13,y:3,tacticalLevel:0},to:{x:13,y:4,tacticalLevel:1}}],
  enemies:[...(contact?[{...base,id:'target',x:15,y:10,tacticalLevel:0,hp:500,maxHp:500,stance:'standing',movementMode:'walk'}]:[]),{...base,id:'hidden',x:hiddenX,y:16,tacticalLevel:0,stance:'standing',movementMode:'walk'}],
  artillery:[],npcs:[]};
 const declaration=structuredClone({players,options}),battle=createBattle(players,options);assert.deepEqual({players,options},declaration);assert.equal(battle.units.filter(unit=>unit.side==='player').length,9);assert.deepEqual(validateBattleSnapshot(JSON.parse(JSON.stringify(battle))),battle);return battle;
}
function doorInvestigationReady(start){
 const check=battle=>{assert.equal(battle.status,'active');if(actor(battle,'target')){assert.equal(battle.mode,'combat');assert.equal(teamCanSee(battle,'player',actor(battle,'target')),true,'The fresh roof-edge observer must keep a current actual squad sighting.');}};
 check(start);const ready=investigationReady(start);check(ready.battle);return ready;
}
const clinicDoor=battle=>battle.wallEdges.find(edge=>edge.doorId==='clinic-exit');
const clinicDoorRef=battle=>{const door=clinicDoor(battle);return {kind:'door',id:door.doorId,wallEdgeId:wallEdgeId(door),x:door.x,y:door.y,axis:door.axis,tacticalLevel:0};};
function fixedDoorProperty(start,after,{opened=false,reloaded=[]}={}){
 fixed(start,after,{reloaded});heldInvestigationPosts(start,after);
 for(const unit of start.units.filter(unit=>unit.side==='player')){const current=actor(after,unit.id);for(const key of ['hp','bleeding','bandaged','medkits','weapon','blade','weaponInstanceId','weaponMetadata','outfit','headwear','legwear'])assert.deepEqual(current[key],unit[key],unit.id+' '+key);}
 const expected=structuredClone(start.wallEdges);if(opened)Object.assign(expected.find(edge=>edge.doorId==='clinic-exit'),{open:true,blocked:false,blocksSight:false});assert.deepEqual(after.wallEdges,expected);
}

