 assert.equal(canSee(start,initial,actor(start,'target')),false);assert.equal(teamCanSee(start,'player',actor(start,'target')),true);assert.equal(canSee(start,initial,clinicDoor(start)),true);assert.equal(policy.sharedFallback(start,initial),null);
