 const open=policy.sharedFallback(battle,unit),local=environmentPreview(publicRouteView(battle,unit),unit,clinicDoorRef(battle),'open');assert.equal(local.valid,true);assert.deepEqual(open,local.action);const closed=battle;battle=investigationStep(battle,open);orders.push(open);assert.equal(actor(battle,'courier').ap,unit.ap-local.pa);assert.equal(clinicDoor(battle).open,true);assert.equal(battle.elapsedSeconds,closed.elapsedSeconds);fixedDoorProperty(start,battle,{opened:true});
 const opened=structuredClone(battle),inside=actor(battle,'courier'),far=wallEdgeCells(clinicDoor(battle)).find(point=>point.y===8),crossing=policy.controller(battle,inside)??policy.sharedFallback(battle,inside),crossingQuote=getReachable(publicRouteView(battle,inside),inside,{stopAt:point=>sameCell(point,far)})[0];
 assert.deepEqual(crossing,{type:'move',unitId:'courier',...spacePoint(far)},'The policy must finish the actual opened exit before general cover search.');assert.ok(crossingQuote.cost>0&&crossingQuote.cost<=24&&crossingQuote.path.length<=3&&crossingQuote.path.every(point=>sameSurface(point,inside)));assert.ok(sameCell(crossingQuote.path.at(-2)??inside,inside));assert.ok(inside.ap-crossingQuote.cost>=actionCosts(battle,inside).fire+2*actionCosts(battle,inside).aim);assert.deepEqual(policy.sharedFallback(battle,inside),crossing);assert.deepEqual(battle,opened);
 let fire=null,crossed=false;
 for(let step=0;step<24&&!fire;step++){
  unit=actor(battle,'courier');const ordinary=policy.controller(battle,unit),action=ordinary??policy.sharedFallback(battle,unit);
  if(action?.type==='fire'){safeShot(battle,unit,action);fire=action;break;}
  if(!action){assert.ok(battle.turn<28);const end={type:'endTurn'};battle=investigationStep(battle,end);orders.push(end);continue;}
  assert.ok(['move','look','stance'].includes(action.type));if(step===0)assert.deepEqual(action,crossing);if(!ordinary&&action.type==='move'){const route=getReachable(publicRouteView(battle,unit),unit,{stopAt:point=>sameCell(point,action)})[0];assert.ok(route.cost>0&&route.cost<=24&&route.path.length<=3&&route.path.every(point=>sameSurface(point,unit)));}battle=investigationStep(battle,action);orders.push(action);if(step===0){assert.ok(sameCell(actor(battle,'courier'),far));assert.equal(actor(battle,'courier').ap,inside.ap-crossingQuote.cost);assert.ok(actor(battle,'courier').energy<inside.energy);assert.equal(battle.elapsedSeconds,opened.elapsedSeconds);}crossed||=actor(battle,'courier').y>=8;fixedDoorProperty(start,battle,{opened:true});
 }
 assert.ok(crossed,'The actual living courier crosses the paid opened leaf.');assert.ok(fire,'The successful fresh prefix must earn a real safe shot under the unchanged battle limits.');const shooter=actor(battle,'courier'),cost=actionCosts(battle,shooter,actor(battle,fire.targetId));battle=investigationStep(battle,fire);orders.push(fire);assert.equal(rounds(actor(battle,'courier')),rounds(initial)-1);assert.equal(actor(battle,'courier').condition,initial.condition-1);assert.equal(actor(battle,'courier').ap,shooter.ap-cost.fire-(fire.aim??0)*cost.aim);
 let reload=policy.controller(battle,actor(battle,'courier'));for(let step=0;reload?.type!=='reload'&&step<3;step++){assert.ok(!reload||reload.type==='stance');const action=reload??{type:'endTurn'};battle=investigationStep(battle,action);orders.push(action);reload=policy.controller(battle,actor(battle,'courier'));}assert.equal(reload?.type,'reload');const empty=actor(battle,'courier');battle=investigationStep(battle,reload);orders.push(reload);assert.equal(actor(battle,'courier').ap,empty.ap-actionCosts(battle,empty).reload);assert.equal(actor(battle,'courier').loaded,1);assert.equal(rounds(actor(battle,'courier')),rounds(initial)-1);fixedDoorProperty(start,battle,{opened:true,reloaded:['courier']});assert.deepEqual(investigationReplay(start,orders),battle);assert.deepEqual(start,before);
