 for(let step=0;step<64&&actor(battle,'courier').ap>=actionCosts(battle,actor(battle,'courier')).fire;step++){const unit=actor(battle,'courier'),look={type:'look',unitId:unit.id,x:unit.facing===2?0:25,y:unit.y,tacticalLevel:0},quote=lookPreview(battle,unit,look);assert.ok(quote.valid&&!quote.prepare&&quote.pa>0);const previous=unit.ap;battle=investigationStep(battle,look);orders.push(look);assert.equal(actor(battle,'courier').ap,previous-quote.pa);}
 assert.ok(actor(battle,'courier').ap<actionCosts(battle,actor(battle,'courier')).fire);assert.equal(policy.sharedFallback(battle,actor(battle,'courier')),null);fixedDoorProperty(start,battle);for(const key of ['inventory','loaded','ammo','condition','medkits','hp','bleeding','bandaged'])assert.deepEqual(actor(battle,'courier')[key],actor(start,'courier')[key]);assert.deepEqual(investigationReplay(ready,orders),battle);for(const unit of battle.units.filter(unit=>unit.side==='player'&&unit.id!=='courier'))assert.equal(policy.sharedFallback(battle,unit),null);assert.deepEqual(start,before);
