import {lowerWeapon} from '../game/weapon-readiness.js';

// A new public forest corner, not a captured map: crouched ground progress
// leaves twenty cover while a roof observer sees the living contact past a wall.
// Both access owners, the physician, wounds and every finite item precede create.
function walkingInvestigationArena({courier={},contact=true,blocked=false,crew=false,hiddenX=21}={}){
 const width=24,height=18,base={hp:100,maxHp:100,bleeding:0,bandaged:0,energy:100,fatigue:0,morale:90,weapon:0,blade:0,loaded:0,ammo:0,condition:100,medical:0,medkits:0,marksmanship:0,stance:'prone',movementMode:'prone',facing:3,activeSlot:'unarmed',patrol:false,overwatch:false};
 const posts=[['guard',13,7],['physician',14,4],['patient',14,5],['west-owner',11,6],['north-owner',13,4],['reserve1',11,5],['reserve2',12,5],['reserve3',13,5]];
 const players=posts.map(([id,x,y])=>({...base,id,x,y,tacticalLevel:1,...(id==='guard'?{stance:'standing',movementMode:'walk'}:{}),...(id==='physician'?{medical:90,medkits:3}:{}),...(crew&&['reserve1','reserve2'].includes(id)?{x:id==='reserve1'?2:3,y:id==='reserve1'?13:12,tacticalLevel:0,weapon:1805,loaded:1,ammo:4,activeSlot:'primary',stance:'standing',movementMode:'walk'}:{})}));
 players.push({...base,id:'courier',x:4,y:4,tacticalLevel:0,weapon:1800,loaded:1,ammo:8,marksmanship:100,dexterity:100,agility:100,experienceLevel:8,stance:'crouched',movementMode:'crouch',weaponReady:true,activeSlot:'primary',...courier});
 const options={id:'fresh-clinic-forest-walk',width,height,hour:12,seed:42,exploration:false,deferContact:true,
  tiles:Array.from({length:width*height},(_,i)=>{const x=i%width,y=Math.floor(i/width),wall=x===8&&y<=7||y===14||blocked&&Math.max(Math.abs(x-4),Math.abs(y-4))===1,water=Math.abs(x-15)<=1&&Math.abs(y-9)<=1&&(x!==15||y!==9),forest=x<=4&&y<=4;return {x,y,type:wall?'wall':water?'water':forest?'forest':'grass',blocked:wall||water,blocksSight:wall,cover:wall?40:forest?20:0};}),
  upperSurfaces:Array.from({length:16},(_,i)=>({id:'walking-roof:'+i,x:11+i%4,y:4+Math.floor(i/4),tacticalLevel:1,elevation:3,type:'floor',kind:'roof',blocked:false,cover:30})),
  climbLinks:[{id:'walking-west',kind:'climb',from:{x:10,y:6,tacticalLevel:0},to:{x:11,y:6,tacticalLevel:1}},{id:'walking-north',kind:'climb',from:{x:13,y:3,tacticalLevel:0},to:{x:13,y:4,tacticalLevel:1}}],
  enemies:[...(contact?[{...base,id:'target',x:15,y:9,tacticalLevel:0,hp:500,maxHp:500,stance:'standing',movementMode:'walk'}]:[]),{...base,id:'hidden',x:hiddenX,y:16,tacticalLevel:0,stance:'standing',movementMode:'walk'}],
  artillery:crew?[{id:'walking-finite-gun',type:'bronze4',side:'player',x:3,y:13,facing:3,loaded:true,ammo:2}]:[],npcs:[]};
 const declaration=structuredClone({players,options}),battle=createBattle(players,options);assert.deepEqual({players,options},declaration);assert.equal(battle.units.filter(unit=>unit.side==='player').length,9);assert.deepEqual(validateBattleSnapshot(JSON.parse(JSON.stringify(battle))),battle);return battle;
}
function publicWalkingPose(battle,unit){
 const paid=stanceCost(unit,'standing'),walking={...unit,stance:'standing',movementMode:'walk',ap:unit.ap-paid,braced:false,overwatch:false};lowerWeapon(walking);const view=publicRouteView(battle,unit),planning={...view,units:view.units.map(other=>other.id===unit.id?walking:other)};return {paid,walking,planning,costs:actionCosts(planning,walking)};
}

test('a crouched clinic forest hold pays one Native walk prefix including its rise before real finite fire and reload',()=>{
 const start=walkingInvestigationArena(),before=structuredClone(start),policy=rescueClinicDefenseController(start),initial=actor(start,'courier');assert.equal(canSee(start,initial,actor(start,'target')),false);assert.equal(teamCanSee(start,'player',actor(start,'target')),true);assert.equal(policy.sharedFallback(start,initial),null);
 let {battle,orders}=investigationReady(start);const unit=actor(battle,'courier'),target=actor(battle,'target'),view=publicRouteView(battle,unit);assert.equal(battle.mode,'combat');assert.equal(teamCanSee(battle,'player',target),true);for(const member of battle.units.filter(unit=>unit.side==='player'))assert.equal(policy.controller(battle,member),null);assert.equal(choosePlayerSharedSightingInvestigation(view,unit,target),null,'The original crouched investigator really holds at this fresh cover corner.');
 const quote=publicWalkingPose(battle,unit),selected=choosePlayerSharedSightingInvestigation(quote.planning,quote.walking,target);assert.equal(selected?.type,'move');const full=getReachable(quote.planning,quote.walking,{stopAt:point=>sameCell(point,selected)})[0];assert.ok(full.cost>0&&full.cost<=24&&full.path.length<=3);assert.ok(quote.paid+full.cost>24,'The new action must pay a strict prefix, not the unaffordable complete standing proposal.');
 const move=policy.sharedFallback(battle,unit);assert.equal(move?.type,'move');assert.equal(move.movement,'walk');const prefix=getReachable(quote.planning,quote.walking,{stopAt:point=>sameCell(point,move)})[0];assert.ok(prefix.cost>0&&quote.paid+prefix.cost<=24&&prefix.path.length>0&&prefix.path.length<full.path.length&&prefix.path.length<=3);assert.deepEqual(prefix.path,full.path.slice(0,prefix.path.length));assert.ok(prefix.path.every(point=>sameSurface(point,unit)&&(point.kind===undefined||point.kind==='move')));assert.ok(quote.walking.ap-prefix.cost>=quote.costs.fire+2*quote.costs.aim);
 const copy=structuredClone(battle);assert.deepEqual(policy.sharedFallback(battle,unit),move);assert.deepEqual(battle,copy);const window=openingControlWindow(battle,{controller:policy.controller,sharedFallback:policy.sharedFallback});assert.deepEqual(window.orders,[move]);assert.deepEqual(window.sharedInvestigation,move);const moved=investigationStep(battle,move);assert.deepEqual(window.battle,moved);assert.ok(sameCell(actor(moved,'courier'),move));assert.equal(actor(moved,'courier').stance,'standing');assert.equal(actor(moved,'courier').movementMode,'walk');assert.notEqual(actor(moved,'courier').weaponReady,true);assert.equal(actor(moved,'courier').ap,unit.ap-quote.paid-prefix.cost);assert.ok(actor(moved,'courier').energy<unit.energy);assert.equal(moved.elapsedSeconds,battle.elapsedSeconds+COMBAT_ROUND_SECONDS);assert.equal(rounds(actor(moved,'courier')),rounds(unit));assert.equal(actor(moved,'courier').condition,unit.condition);heldInvestigationPosts(start,moved);fixed(start,moved);orders.push(move);battle=moved;
 let fire=null;
 for(let step=0;step<32&&!fire;step++){
  const current=actor(battle,'courier'),ordinary=policy.controller(battle,current),action=ordinary??policy.sharedFallback(battle,current);if(action?.type==='fire'){safeShot(battle,current,action);fire=action;break;}
  if(!action){assert.ok(battle.turn<28);const end={type:'endTurn'};battle=investigationStep(battle,end);orders.push(end);continue;}
  assert.ok(['move','look','stance'].includes(action.type));if(!ordinary&&action.type==='move'){const posed=action.movement==='walk'?publicWalkingPose(battle,current):{paid:0,walking:current,planning:publicRouteView(battle,current),costs:actionCosts(battle,current)},route=getReachable(posed.planning,posed.walking,{stopAt:point=>sameCell(point,action)})[0];assert.ok(route.cost>0&&posed.paid+route.cost<=24&&route.path.length<=3&&route.path.every(point=>sameSurface(point,current)));assert.ok(posed.walking.ap-route.cost>=posed.costs.fire+2*posed.costs.aim);}battle=investigationStep(battle,action);orders.push(action);heldInvestigationPosts(start,battle);fixed(start,battle);
 }
 assert.ok(fire,'The actual selected prefixes must reach a safe finite shot.');const shooter=actor(battle,'courier'),cost=actionCosts(battle,shooter,actor(battle,fire.targetId));battle=investigationStep(battle,fire);orders.push(fire);assert.equal(rounds(actor(battle,'courier')),rounds(initial)-1);assert.equal(actor(battle,'courier').condition,initial.condition-1);assert.equal(actor(battle,'courier').ap,shooter.ap-cost.fire-(fire.aim??0)*cost.aim);
 let reload=policy.controller(battle,actor(battle,'courier'));for(let step=0;reload?.type!=='reload'&&step<3;step++){assert.ok(!reload||reload.type==='stance');const action=reload??{type:'endTurn'};battle=investigationStep(battle,action);orders.push(action);reload=policy.controller(battle,actor(battle,'courier'));}assert.equal(reload?.type,'reload');const empty=actor(battle,'courier');battle=investigationStep(battle,reload);orders.push(reload);assert.equal(actor(battle,'courier').ap,empty.ap-actionCosts(battle,empty).reload);assert.equal(actor(battle,'courier').loaded,1);assert.equal(rounds(actor(battle,'courier')),rounds(initial)-1);heldInvestigationPosts(start,battle);fixed(start,battle,{reloaded:['courier']});assert.deepEqual(investigationReplay(start,orders),battle);assert.deepEqual(start,before);
});

