 context.eligibleIds.push('invented');row.calls.shared=-1;walk.actor.ap=-1;walk.route.path[0].x=-1;walk.prefixes[0].quote.path.length=0;assert.equal(observed.diagnosticContext().actors[0].calls.shared,2);assert.equal(observed.diagnosticContext().actors[0].latest.paidWalking.actor.ap,unit.ap);
 for(let repeat=0;repeat<24;repeat++)assert.deepEqual(observed.sharedFallback(battle,unit),expected);
 const bounded=observed.diagnosticContext();assert.equal(bounded.actors.length,1);assert.deepEqual(bounded.eligibleIds,['courier']);assert.equal(bounded.actors[0].calls.shared,26);assert.equal(bounded.actors[0].calls.paidWalking,25);assert.ok(Object.keys(bounded.actors[0].latest).length<=3);for(const prefix of bounded.actors[0].latest.paidWalking.prefixes)assert.ok(prefix.quote.path.length<=3);
 const after=investigationStep(battle,action);assert.deepEqual(after,investigationStep(battle,expected));assert.deepEqual(investigationReplay(start,[...orders,action]),after);heldInvestigationPosts(start,after);fixed(start,after);assert.deepEqual(start,before);
 // A non-null shared look has its own quote row and never enters paidWalking.
