// Independent longer obstacle: no three-step endpoint can see across this
// wall, while the roof edge supplies a current public island contact. Every
// condition, finite item, role, obstacle and access link precedes the factory.
function firingRouteArena({courier={},contact=true,sealed=false,crew=false,hiddenX=21}={}){
 const width=24,height=18,base={hp:100,maxHp:100,bleeding:0,bandaged:0,energy:100,fatigue:0,morale:90,weapon:0,blade:0,loaded:0,ammo:0,condition:100,medical:0,medkits:0,marksmanship:0,stance:'prone',movementMode:'prone',facing:3,activeSlot:'unarmed',patrol:false,overwatch:false};
 const posts=[['guard',13,7],['physician',14,4],['patient',14,5],['west-owner',11,6],['north-owner',13,4],['reserve1',11,5],['reserve2',12,5],['reserve3',13,5]];
 const players=posts.map(([id,x,y])=>({...base,id,x,y,tacticalLevel:1,...(id==='guard'?{stance:'standing',movementMode:'walk'}:{}),...(id==='physician'?{medical:90,medkits:3}:{}),...(crew&&['reserve1','reserve2'].includes(id)?{x:id==='reserve1'?2:3,y:id==='reserve1'?13:12,tacticalLevel:0,weapon:1805,loaded:1,ammo:4,activeSlot:'primary',stance:'standing',movementMode:'walk'}:{})}));
 players.push({...base,id:'courier',x:4,y:6,tacticalLevel:0,weapon:1800,loaded:1,ammo:8,marksmanship:100,dexterity:100,agility:100,experienceLevel:8,stance:'crouched',movementMode:'crouch',weaponReady:true,activeSlot:'primary',...courier});
 const options={id:'fresh-clinic-long-public-firing-route',width,height,hour:12,seed:42,exploration:false,deferContact:true,
  tiles:Array.from({length:width*height},(_,i)=>{const x=i%width,y=Math.floor(i/width),wall=x===6&&(sealed||y<=10)||y===14,water=Math.abs(x-15)<=1&&Math.abs(y-9)<=1&&(x!==15||y!==9),forest=x===4&&y===6;return {x,y,type:wall?'wall':water?'water':forest?'forest':'grass',blocked:wall||water,blocksSight:wall,cover:wall||forest?40:0};}),
  upperSurfaces:Array.from({length:16},(_,i)=>({id:'firing-route-roof:'+i,x:11+i%4,y:4+Math.floor(i/4),tacticalLevel:1,elevation:3,type:'floor',kind:'roof',blocked:false,cover:30})),
  climbLinks:[{id:'firing-route-west',kind:'climb',from:{x:10,y:6,tacticalLevel:0},to:{x:11,y:6,tacticalLevel:1}},{id:'firing-route-north',kind:'climb',from:{x:13,y:3,tacticalLevel:0},to:{x:13,y:4,tacticalLevel:1}}],
  enemies:[...(contact?[{...base,id:'target',x:15,y:9,tacticalLevel:0,hp:500,maxHp:500,stance:'standing',movementMode:'walk'}]:[]),{...base,id:'hidden',x:hiddenX,y:16,tacticalLevel:0,stance:'standing',movementMode:'walk'}],
  artillery:crew?[{id:'firing-route-finite-gun',type:'bronze4',side:'player',x:3,y:13,facing:3,loaded:true,ammo:2}]:[],npcs:[]};
 const declaration=structuredClone({players,options}),battle=createBattle(players,options);assert.deepEqual({players,options},declaration);assert.equal(battle.units.filter(unit=>unit.side==='player').length,9);assert.deepEqual(validateBattleSnapshot(JSON.parse(JSON.stringify(battle))),battle);return battle;
}
function firingRoutePose(battle,unit){
 const paid=stanceCost(unit,'standing'),walking={...unit,stance:'standing',movementMode:'walk',ap:unit.ap-paid,braced:false,overwatch:false};if(paid>0)lowerWeapon(walking);const view=publicRouteView(battle,unit),planning={...view,units:view.units.map(other=>other.id===unit.id?walking:other)};return {paid,walking,planning};
}

